steps.seedCode:
const http = require('http');

const server = http.createServer((req, res) => {
  // Check URL and apply middleware to '/admin' route here
});

const user = {
  id: 1,
  name: 'Admin User',
  permissions: ['admin', 'read', 'write']
};

function checkPermission(user, requiredPermission) {
  return user.permissions.includes(requiredPermission);
}

function permissionMiddleware(req, res, next) {
  const requiredPermission = 'admin';
  if (checkPermission(user, requiredPermission)) {
    next();
  } else {
    res.writeHead(403, { 'Content-Type': 'text/plain' });
    res.end('Access forbidden: insufficient permissions');
  }
}

function adminRouteHandler(req, res) {
  res.writeHead(200, { 'Content-Type': 'text/plain' });
  res.end('Welcome to the admin panel');
}

server.listen(3000, () => {
  console.log('Server running on port 3000');
});

